import{WETLAND_ROLES}from'./role-registration.mjs';import{createFrameLighting}from'./environment/common/frame-lighting.mjs';
const ROWS=WETLAND_ROLES.filter(r=>r.kind==='trainer'),sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadWetlandNPCs({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b])),signal,canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}={}){let closed=false,canvas=null;const data=[],tint=createFrameLighting({nightTint:[.4,.47,.6]});const check=()=>{if(closed||signal?.aborted)throw Error('WETLAND_NPC_CLOSED')};const dispose=()=>{if(closed)return;closed=true;data.length=0;try{if(canvas)canvas.width=canvas.height=1}finally{canvas=null}};try{canvas=canvasFactory(107,107);for(const r of ROWS){check();const response=await fetcher(new URL('../../'+r.atlas.src,import.meta.url),{signal});if(!response.ok)throw Error('WETLAND_NPC_ASSET');const bytes=new Uint8Array(await response.arrayBuffer());check();if(await sha(bytes)!==r.atlas.sha256)throw Error('WETLAND_NPC_ATLAS_PIN');check();let image,error,rgba;try{image=await decode(bytes);check();if(image.width!==r.atlas.width||image.height!==r.atlas.height)throw Error('WETLAND_NPC_DIMENSIONS');const g=canvas.getContext('2d'),[x,y,w,h]=r.atlasFrame.rect;g.clearRect(0,0,107,107);g.imageSmoothingEnabled=false;g.drawImage(image,x,y,w,h,53-w*80/h/2,10,w*80/h,80);rgba=g.getImageData(0,0,107,107).data}catch(e){error=e}finally{try{image?.close?.()}catch(e){error??=e}}if(error)throw error;check();data.push({row:r,rgba})}return Object.freeze({drawLayers(ctx,origin,nightMix){check();return data.map(({row:r,rgba})=>({y:r.npcFoot[1],draw(){check();const g=canvas.getContext('2d'),image=g.createImageData(107,107);tint(rgba,image.data,nightMix);g.putImageData(image,0,0);ctx.drawImage(canvas,r.npcFoot[0]-origin[0]-53,r.npcFoot[1]-origin[1]-90)}}))},dispose})}catch(e){try{dispose()}catch{}throw e}}
